const TERMS=`REGULAMIN WERSJI TESTOWEJ TOGETHER — 18.11.2026

1. TOGETHER służy do poznawania osób i organizowania spotkań. Korzystać mogą wyłącznie osoby pełnoletnie.
2. Użytkownik odpowiada za podane treści, zdjęcia i wiadomości. Zabronione są: podszywanie się, nękanie, groźby, treści bezprawne, seksualizacja osób małoletnich, spam i publikowanie cudzych danych.
3. Pierwsze spotkania wybieraj w miejscu publicznym. Nie wysyłaj pieniędzy i nie udostępniaj dokumentów ani haseł.
4. TOGETHER może blokować treści lub konta naruszające zasady. Zgłoszenie nie zastępuje kontaktu z policją lub numerem alarmowym w sytuacji zagrożenia.
5. Usługa jest wersją testową. Przed uruchomieniem komercyjnym dokument wymaga uzupełnienia danych właściciela, reklamacji i właściwego prawa.`;
const PRIVACY=`POLITYKA PRYWATNOŚCI — WERSJA ROBOCZA 18.11.2026

TOGETHER przetwarza adres e-mail i identyfikator konta w celu logowania; dane wizytówki, zdjęcie, wybory, dopasowania i wiadomości w celu świadczenia funkcji aplikacji; zgłoszenia i blokady w celu bezpieczeństwa.

Dane są przechowywane w Supabase, a aplikacja jest publikowana w Vercel. Zdjęcie wybrane do widocznej wizytówki jest publicznie dostępne pod adresem pliku. Pozostałe tabele są chronione uprawnieniami konta.

Użytkownik może żądać dostępu, sprostowania, usunięcia, ograniczenia, przeniesienia danych lub wnieść sprzeciw i skargę do Prezesa UODO.

UWAGA: przed publicznym uruchomieniem właściciel musi uzupełnić tożsamość i kontakt administratora, podstawy prawne, okresy retencji, odbiorców i zasady transferów danych.`;
export function createSafety(api,{root,notice}){
 if(!document.querySelector('link[href="legal.css"]')){const l=document.createElement('link');l.rel='stylesheet';l.href='legal.css';document.head.append(l);}
 const dialog=(id,title,text)=>{const d=document.createElement('dialog');d.id=id;const h=document.createElement('h2');h.textContent=title;const copy=document.createElement('div');copy.className='legal-copy';copy.textContent=text;const close=document.createElement('button');close.className='primary';close.textContent='Zamknij';close.onclick=()=>d.close();d.append(h,copy,close);root.append(d);return d;};
 const terms=dialog('terms-dialog','Regulamin TOGETHER',TERMS),privacy=dialog('privacy-dialog','Polityka prywatności',PRIVACY),links=document.createElement('div');links.className='legal-links';links.innerHTML='<button type="button">Regulamin</button><button type="button">Polityka prywatności</button>';links.children[0].onclick=()=>terms.showModal();links.children[1].onclick=()=>privacy.showModal();root.querySelector('footer').before(links);
 const forgot=document.createElement('button');forgot.className='text-button';forgot.type='button';forgot.textContent='Nie pamiętam hasła';root.querySelector('#resend').after(forgot);forgot.onclick=async()=>{const email=prompt('Podaj adres e-mail konta TOGETHER:');if(!email)return;try{await api.recover(email.trim());notice('Jeśli konto istnieje, wysłaliśmy wiadomość do ustawienia nowego hasła.');}catch(e){notice(e.message,true);}};
 const recovery=document.createElement('section');recovery.className='card';recovery.hidden=true;recovery.innerHTML='<h2>Ustaw nowe hasło</h2><form><label>Nowe hasło</label><input type="password" minlength="8" maxlength="128" required><label>Powtórz hasło</label><input type="password" minlength="8" maxlength="128" required><button class="primary">Zapisz nowe hasło</button></form>';root.querySelector('main').append(recovery);recovery.querySelector('form').onsubmit=async e=>{e.preventDefault();const [a,b]=[...e.currentTarget.querySelectorAll('input')].map(x=>x.value);if(a!==b){notice('Hasła muszą być takie same.',true);return;}try{await api.updatePassword(a);recovery.hidden=true;notice('Hasło zostało zmienione.');location.reload();}catch(x){notice(x.message,true);}};
 async function ensureConsent(){if(await api.myConsent())return;const d=document.createElement('dialog');d.className='consent-dialog';d.innerHTML='<h2>Zanim przejdziesz dalej</h2><p>TOGETHER jest przeznaczone wyłącznie dla osób pełnoletnich.</p><form><label class="checkbox"><input type="checkbox" required> Potwierdzam, że mam co najmniej 18 lat.</label><label class="checkbox"><input type="checkbox" required> Akceptuję regulamin i zapoznałem/am się z polityką prywatności.</label><button class="primary">Akceptuję i przechodzę dalej</button></form>';root.append(d);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api.acceptRules();d.close();d.remove();}catch(x){notice(x.message,true);}};d.showModal();}
 const danger=document.createElement('section');danger.className='account-danger';danger.innerHTML='<h3>Usunięcie konta</h3><p class="muted">Trwale usuwa konto, profil, spotkania, dopasowania, wiadomości i bieżące zdjęcie. Tej operacji nie można cofnąć.</p><button type="button" class="text-button danger">Usuń moje konto</button>';root.querySelector('#account-panel .card').append(danger);
 danger.querySelector('button').onclick=async()=>{const confirmation=prompt('Aby trwale usunąć konto i dane, wpisz dokładnie: USUŃ KONTO');if(confirmation===null)return;if(confirmation!=='USUŃ KONTO'){notice('Konto nie zostało usunięte — tekst potwierdzenia jest nieprawidłowy.',true);return;}if(!confirm('To ostatnie potwierdzenie. Trwale usunąć konto TOGETHER?'))return;try{const profile=await api.myDiscoveryProfile();await api.deleteOwnAccount(confirmation,profile?.photo_path);notice('Konto i dane zostały usunięte.');location.reload();}catch(x){notice(x.message,true);}};
 return{ensureConsent,showRecovery(){root.querySelector('#auth-view').hidden=true;recovery.hidden=false;}};
}
